<?php require_once __DIR__ . '/_boot.php';
$from = $_GET['from'] ?? date('Y-m-01'); $to = $_GET['to'] ?? date('Y-m-d');
$rows=[]; try { $st=db()->prepare("SELECT s.transaction_code, MIN(s.sold_at) sold_at, COALESCE(u.name,'-') cashier, s.payment_method, COALESCE(s.payment_bank,s.payment_channel_name,'') bank, SUM(s.qty) qty, SUM(s.total) total FROM sales s LEFT JOIN users u ON u.id=s.created_by WHERE s.branch_id=? AND DATE(s.sold_at) BETWEEN ? AND ? AND s.include_in_sales_report=1 AND (s.return_reason IS NULL OR s.return_reason='') GROUP BY s.transaction_code,s.payment_method,bank,cashier ORDER BY sold_at DESC LIMIT 300"); $st->execute([$unitId,$from,$to]); $rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[]; } catch(Throwable $e) { $err=$e->getMessage(); } ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Riwayat Penjualan Cabang</title><link rel="icon" href="<?php echo e(favicon_url()); ?>"><link rel="stylesheet" href="<?php echo e(asset_url('assets/app.css')); ?>"><style><?php echo $customCss; ?></style></head><body><div class="container"><?php include __DIR__ . '/_sidebar.php'; ?><div class="main"><div class="topbar"><button class="btn" data-toggle-sidebar type="button">Menu</button><strong>Riwayat Penjualan Cabang</strong></div><div class="content"><div class="card"><form class="grid cols-4"><input type="hidden" name="unit_id" value="<?php echo e((string)$unitId); ?>"><div class="row"><label>Dari</label><input type="date" name="from" value="<?php echo e($from); ?>"></div><div class="row"><label>Sampai</label><input type="date" name="to" value="<?php echo e($to); ?>"></div><div class="row" style="align-self:end"><button class="btn" type="submit">Filter</button></div></form></div><div class="card"><table class="table"><thead><tr><th>Waktu</th><th>No</th><th>Kasir</th><th>Metode</th><th>Bank</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?php echo e($r['sold_at']); ?></td><td><?php echo e($r['transaction_code']); ?></td><td><?php echo e($r['cashier']); ?></td><td><?php echo e($r['payment_method']); ?></td><td><?php echo e($r['bank']); ?></td><td><?php echo e((string)$r['qty']); ?></td><td><?php echo e(format_money($r['total'])); ?></td></tr><?php endforeach; if(empty($rows)): ?><tr><td colspan="7">Belum ada data.</td></tr><?php endif; ?></tbody></table></div></div></div></div><script src="<?php echo e(asset_url('assets/app.js')); ?>"></script></body></html>
